def doc_book_label(book_id):
    return _BOOK_LABELS_FOR_DOC[book_id]


def bhs_simple_shift_cases():
    return tuple(
        case_rec
        for case_rec in CASES
        if case_rec.renderer_kind == RENDERER_KIND_SIMPLE_SHIFT
        and case_rec.appears_in_bhs
    )


def bhs_early_one_vs_many_cases():
    return tuple(
        case_rec
        for case_rec in CASES
        if case_rec.renderer_kind == RENDERER_KIND_ONE_VS_MANY
        and case_rec.appears_in_bhs
        and case_rec.split_part_suffixes
        and case_rec.last_shifted_vrnu is not None
        and len(case_rec.split_part_suffixes) == 2
    )


def bhs_late_one_vs_many_cases():
    return tuple(
        case_rec
        for case_rec in CASES
        if case_rec.renderer_kind == RENDERER_KIND_ONE_VS_MANY
        and case_rec.appears_in_bhs
        and case_rec.split_part_suffixes
        and case_rec.last_shifted_vrnu is not None
        and len(case_rec.split_part_suffixes) == 4
    )


